INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (10, 'Audi RS7 Sportback', 'audi-rs7-sportback', '600 PS V8 motorun kükreyişi ile zarif sedan konforu bir arada. Dinamik tasarımıyla dikkat çeken Quattro performans canavarı.', 'Araç RS Dinamik Paket Plus donanımına sahiptir. İç mekanda RS logolu Valcona deri spor koltuklar, Alcantara tavan döşemesi ve karbon fiber detaylar kullanılmıştır. Bang & Olufsen 3D Advanced Ses Sistemi, Lazer Matrix LED farlar ve vakumlu kapılar mevcuttur. İlk sahibinden, hatasız ve çiziksizdir.', 'https://images.unsplash.com/photo-1603584173870-7f23fdae1b7a?q=80&w=1080', 'Spor Sedan', false, '["audi","rs7","sportback","quattro","spor","sedan","lüks"]', '2026-05-23T15:21:03.365649+00:00', 2024, 8500, 145000, 40000, 2450, 1.85, 48, '015737641145', '["RS Spor Süspansiyon","Bang & Olufsen Ses Sistemi","Lazer Matrix Farlar","Gece Görüş Asistanı","Vakumlu Kapılar"]', '["https://i.pinimg.com/736x/52/09/47/5209478d5bd37502d0ca971c72c704ac.jpg","https://i.pinimg.com/1200x/c9/0b/80/c90b8086a5f6724cb130eca9d92bd318.jpg"]', 7);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (9, 'Mercedes-AMG G 63', 'mercedes-amg-g-63', 'İkonik tasarım ve 585 beygirlik V8 biturbo motorun gücü bir arada. Tam donanımlı, hatasız lüks SUV.', 'Aracımız "G Manufaktur" özel serisidir. Özel renk, Nappa deri koltuklar, karbon fiber detaylar ve AMG Gece Paketi (Night Package) mevcuttur. Tüm bakımları yetkili servisinde yapılmıştır. Çiziksiz, kazasız ve masrafsızdır. Arka eğlence paketi ve 360 derece kamera sistemi bulunur.', 'https://images.unsplash.com/photo-1520031441872-265e4ff70366?q=80&w=1080', 'Lüks SUV', true, '["mercedes","amg","g63","suv","lüks","4x4","offroad"]', '2026-05-23T15:18:34.153492+00:00', 2023, 12500, 215000, 60000, 3650, 1.95, 48, '015737641145', '["AMG Gece Paketi","Burmester 3D Ses","Masajlı Koltuklar","360 Kamera","Arka Eğlence Sistemi"]', '["https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1779549741418-89x9cc.jpeg","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1779549743034-fln81.jpeg","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1779549743841-dmawx7.jpeg"]', 1);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (8, 'Porsche 911 Turbo S', 'porsche-911-turbo-s', '650 PS güç ve 0-100 km/s sadece 2.7 saniye. Kusursuz aerodinamik tasarıma sahip, hatasız garaj arabası.', 'Araç tamamen yetkili servis bakımlı olup nokta hatasızdır. Sport Chrono Paketi, Porsche Seramik Kompozit Frenler (PCCB) ve Burmester High-End Surround ses sistemi ile donatılmıştır. Seramik kaplaması yeni yapılmış olup, sürekli kapalı garajda muhafaza edilmektedir. ', 'https://images.unsplash.com/photo-1614162692292-7ac56d7f7f1e?q=80&w=1080', 'Lüks Spor', true, '["porsche","911","turbo s","spor","lüks","performans"]', '2026-05-23T14:52:24.470682+00:00', 2024, 3200, 285000, 85000, 4650, 1.89, 48, '015737641145', '["Karbon Seramik Fren","Sport Chrono","Burmester Ses Sistemi","Karbon İç Trim","Koltuk Soğutma"]', '["https://images.unsplash.com/photo-1580273916550-e323be2ae537?q=80&w=1080","https://images.unsplash.com/photo-1614162692292-7ac56d7f7f1e?q=80&w=1080"]', 6);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (16, 'Mercedes-AMG SL 63', 'mercedes-amg-sl-63', '585 beygirlik V8 biturbo motor ve 4MATIC+ dört çeker sistemiyle saf üstü açık sürüş keyfi.', 'Metal tavan yerine geleneksel kumaş tenteye dönüş yapan yeni nesil aerodinamik SL serisi. Araç "Manufaktur Alp Grisi" rengindedir. İçi kırmızı/siyah Nappa deridir. AMG Aerodinamik paketi, arka aks yönlendirme ve Burmester surround ses sistemi mevcuttur. Nokta hatasız ve yetkili bayi çıkışlıdır.', 'https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1780385461048-fvsn1.jpg', 'Cabriolet / Roadster', true, '[]', '2026-06-02T07:29:10.120601+00:00', 2024, 3500, 235000, 70000, 3950, 1.89, 48, '015737641145', '["mercedes","amg","sl63","cabrio","roadster","v8","spor"]', '["https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1780385471380-e2jsnl.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1780385474202-ad7jkv.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1780385475485-pvr6yd.jpg"]', 3);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (13, 'BMW M8 Competition Gran Coupé', 'bmw-m8-competition-gran-coupe', '625 beygir gücündeki V8 motoruyla sınırları zorlayan, 4 kapılı lüks ve performans canavarı.', 'Aracımız lansman rengi olan "Marina Bay Blue" metalik dış renge ve "Silverstone" tam deri merinos iç döşemeye sahiptir. M Karbon dış paket, Bowers & Wilkins Diamond ses sistemi ve lazer farlar mevcuttur. Yetkili bayi çıkışlı olup garantisi devam etmektedir. Kapalı garajda muhafaza edilmiş, kusursuz temizliktedir.', 'https://i.pinimg.com/736x/ce/92/51/ce9251d8edeea5d3f24a59bd18e96bc8.jpg', 'Spor Sedan', true, '["bmw","m8","competition","gran coupe","spor","lüks","v8"]', '2026-05-23T15:39:31.191336+00:00', 2024, 5200, 175000, 50000, 2950, 1.85, 48, '015737641145', '["M Karbon Paket","Bowers & Wilkins Ses","Lazer Farlar","Merinos Deri","Koltuk Havalandırma"]', '["https://i.pinimg.com/736x/ce/92/51/ce9251d8edeea5d3f24a59bd18e96bc8.jpg","https://i.pinimg.com/1200x/ee/d9/98/eed9988e5ff254251db0bb35444866a7.jpg","https://i.pinimg.com/736x/ca/7b/b9/ca7bb90cb8ac9427d4f92c536a43655a.jpg"]', 10);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (12, 'Lamborghini Urus Performante', 'lamborghini-urus-performante', 'Dünyanın ilk Süper SUV''u. 666 beygir güç üreten V8 çift turbolu motor ile yarış pisti ruhunu günlük hayata taşıyor.', 'Araç göz alıcı Giallo Inti (Sarı) renginde olup, tam karbon fiber dış paket ile donatılmıştır. İç mekanda Nero Ade (Siyah) Alcantara ve sarı dikiş detayları hakimdir. Gelişmiş 3D Bang & Olufsen ses sistemi, panoramik cam tavan ve Akrapovic titanyum egzoz sistemi bulunmaktadır. Araç tamamen şeffaf PPF kaplıdır, en ufak bir taş izi veya çizik dahi yoktur.', 'https://en.wikipedia.org/wiki/Special:FilePath/Lamborghini_Urus_SE_001.jpg', 'Süper SUV', true, '["lamborghini","urus","performante","suv","süper araba","lüks","performans"]', '2026-05-23T15:30:58.456357+00:00', 2024, 4200, 315000, 315000, 315000, 1.89, 48, '015737641145', '["Karbon Fiber Paket","Akrapovic Egzoz","Alcantara İç Döşeme","Bang & Olufsen 3D","Panoramik Tavan"]', '["https://en.wikipedia.org/wiki/Special:FilePath/Lamborghini_Urus_SE_001.jpg","https://en.wikipedia.org/wiki/Special:FilePath/Lamborghini_Urus_06.jpg","https://en.wikipedia.org/wiki/Special:FilePath/Lamborghini_Urus_IMG_0003.jpg"]', 8);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (11, 'Bentley Continental GT V8', 'bentley-continental-gt-v8', 'İngiliz zarafeti ve üstün mühendisliğin buluştuğu nokta. 542 beygirlik V8 motoruyla eşsiz bir Grand Tourer deneyimi.', 'Araç Mulliner sürüş spesifikasyonuna sahip, özel sipariş bir modeldir. İç mekanda çift tonlu özel deri döşeme, el işçiliği ahşap kaplamalar ve Naim for Bentley yüksek sadakatli ses sistemi bulunmaktadır. İkonik Bentley Dönen Ekran (Rotating Display) ve tam kapsamlı sürücü asistan paketleri mevcuttur. Tamamen kapalı garajda muhafaza edilmiş olup, adeta showroom kondisyonundadır.', 'https://en.wikipedia.org/wiki/Special:FilePath/2019_Bentley_Continental_GT_V8.jpg', 'Ultra Lüks', true, '["bentley","continental gt","lüks","coupe","v8","grand tourer"]', '2026-05-23T15:29:03.005837+00:00', 2023, 4500, 245000, 75000, 4100, 1.9, 48, '015737641145', '["Mulliner Paket","Bentley Dönen Ekran","Naim Ses Sistemi","Masajlı Koltuklar","Gece Görüş Asistanı"]', '["https://en.wikipedia.org/wiki/Special:FilePath/Bentley_Continental_GT_V8_S_(front).jpg","https://en.wikipedia.org/wiki/Special:FilePath/Bentley_Continental_GT_V8_S_(side).jpg"]', 9);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (18, 'Bentley continnental GT Speed', 'Bentley-continental-gt-speed', '659 beydirlik devasa W12 motoruyla .....', 'Bentley continental GT Speed markanın bugüne kadar ürettiği en dinamik yol otomobilidir. .....', 'https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784190966679-a4zx8i.png', 'ultra lüks coupe', false, '["Bentley","continental","GT Speed","Coupe","W12"]', '2026-07-16T08:41:28.661934+00:00', 2024, 1200, 365000, 115000, 5250, 2.99, 48, '05321256897', '["naim ses sistemi","mullınner sürüş spesifikasyonu","karbon seramik frenler"]', '["https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784191196943-i1rsc.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784191199484-cdq9jg.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784191200993-vxff77.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784191202214-u75kal.png","https://pqwvloxinvbxiaiwalcg.supabase.co/storage/v1/object/public/images/1784191203510-ogwvvm.png"]', 2);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (15, 'Mercedes-Benz S 580 4MATIC', 'mercedes-benz-s-580-4matic', 'Lüksün ve teknolojinin zirvesi. S-Serisi konforu, 503 beygirlik güçlü V8 motor ve üstün sürüş asistanlarıyla yeniden tanımlanıyor.', 'Aracımız "Obsidian Siyah" renginde olup, içi "Macchiato Bej" Nappa deridir. Arka koltuk konfor paketi, arka camlarda perdeler, Burmester 4D High-End ses sistemi ve artırılmış gerçeklikli Head-Up Display bulunmaktadır. Şoförlü olarak uzun yolda kullanılmış, tüm bakımları yetkili servisinde aksatılmadan yapılmıştır. Kozmetik olarak kusursuzdur.', 'https://i.pinimg.com/736x/57/d5/cf/57d5cf290867ab665f8169a5d166f063.jpg', 'Lüks Sedan', true, '[]', '2026-05-23T17:13:26.668484+00:00', 2024, 14999, 185000, 55000, 3100, 2.3, 24, '015737641145', '["Burmester 4D Ses","Arka Koltuk Konfor Paketi","AR Head-Up Display","Masajlı Koltuklar","Arka Aks Yönlendirme"]', '["https://i.pinimg.com/736x/57/d5/cf/57d5cf290867ab665f8169a5d166f063.jpg","https://i.pinimg.com/736x/ae/51/03/ae510332f7f6a4968abeb36968e92444.jpg","https://i.pinimg.com/736x/f2/ea/ea/f2eaea129131dd38ae7f109b43b61e43.jpg"]', 0);
INSERT INTO "contents" ("id", "title", "slug", "summary", "body", "image_url", "category", "status", "tags", "created_at", "year", "mileage", "price", "down_payment", "monthly_rate", "interest_rate", "term_months", "phone", "features", "images", "sort_order") VALUES (14, 'Aston Martin DBX', 'aston-martin-dbx', 'İngiliz asaletini sportif ruhla birleştiren, 550 beygirlik V8 motoruyla sınırları aşan ilk Aston Martin SUV modeli.', 'Araç özel sipariş "Xenon Grey" dış renge ve "Oxford Tan" tam deri iç döşemeye sahiptir. Panoramik cam tavan, ısıtmalı/soğutmalı koltuklar ve Aston Martin premium ses sistemi mevcuttur. Yetkili servis bakımlı olup hiçbir kazası, boyası veya tramer kaydı bulunmamaktadır. Kapalı garajda özenle muhafaza edilmiştir.', 'https://en.wikipedia.org/wiki/Special:FilePath/Aston_Martin_DBX_Auto_Zuerich_2021_IMG_0169.jpg', 'Lüks SUV', false, '[]', '2026-05-23T17:10:01.177257+00:00', 2024, 6500, 265000, 80000, 4250, 1.89, 48, '015737641145', '["Panoramik Tavan","Premium Ses Sistemi","Oxford Deri","360 Kamera","Kör Nokta Asistanı"]', '["https://en.wikipedia.org/wiki/Special:FilePath/Aston_Martin_DBX_IMG_6348.jpg","https://en.wikipedia.org/wiki/Special:FilePath/Aston_Martin_DBX_Retro_Classics_2020_IMG_0218.jpg"]', 4);
